insert into public.clips(id,place_id,publisher_id,data) values('7e460225-9c44-5918-a660-e5afd55c29d4','17a7552b-5573-5f31-a932-99214eca2db1','ae1fe04b-4e55-5710-b478-aa2a6f32f7d4','{"title": "Yosemite in Motion", "caption": "A recorded waterfall view in Yosemite National Park, excerpted from public-domain National Park Service footage.", "video_path": "catalog/videos/yosemite-waterfall.mp4", "cover_path": "catalog/covers/yosemite-waterfall.jpg", "source_url": "https://www.nps.gov/media/video/view.htm?id=A45A7B7C-295C-4718-B5FA-FE30882C291F", "author": "National Park Service", "duration": 10.01, "category": "National Park"}'::jsonb) on conflict(id) do nothing;
insert into public.guides(id,place_id,data) values('a0af4e11-2fee-5be6-8418-aea0df526e5c','3581e286-25db-5eff-848e-10b50af25ac1','{"title": "Paris by the Seine: Field Notes", "intro": "Riverside walks, grand avenues and small neighborhood streets make a Paris day worth leaving open-ended.", "sections": [{"title": "A day with room to wander", "body": "Start with one landmark, then follow the river rather than racing between distant attractions. Pair a monument with a small neighborhood walk for a more varied day."}, {"title": "Plan the practical details", "body": "The official tourism office links district walks, transport options and accessibility information. Confirm arrangements for each attraction directly before you go; booking and access can change."}], "source_name": "Paris je t''aime", "source_url": "https://parisjetaime.com/eng/", "reading_minutes": 2}'::jsonb) on conflict(id) do nothing;
insert into public.guides(id,place_id,data) values('777ba655-213e-5b4e-b855-92a6ccb93408','a42c1b6c-7fcc-51b7-837d-0ee7e3375fbe','{"title": "Colosseum and Ancient Rome: Field Notes", "intro": "Roman stonework and the surrounding archaeological landscape tell a story far larger than one amphitheater.", "sections": [{"title": "Build around your entry slot", "body": "Begin with the official archaeological park website and choose the visit that matches your interests. Colosseum entry uses a reserved time, so plan other stops around that commitment."}, {"title": "Give the wider site time", "body": "The Roman Forum and Palatine form a much broader visit than a quick photograph outside the arena. Read what your selected ticket includes and allow time for walking between areas."}], "source_name": "Parco archeologico del Colosseo", "source_url": "https://colosseo.it/en/opening-times-and-tickets/", "reading_minutes": 2}'::jsonb) on conflict(id) do nothing;
insert into public.guides(id,place_id,data) values('1de34275-77c1-5a3a-91a0-ee8fb9826717','24f0be99-d029-54ae-8584-f9a14f0e17a6','{"title": "Venice Canal Walks: Field Notes", "intro": "Quiet canal corners and weathered bridges reward a slow route through Venice beyond the busiest passages.", "sections": [{"title": "Move at the city''s pace", "body": "Use smaller streets to discover artisan workshops and everyday corners of Venice. On narrow routes, walk to the right in single file so residents and other visitors can pass."}, {"title": "Respect a living place", "body": "Choose proper rest areas, look after waterways and historic spaces, and sort waste responsibly. Check the official city site for current access requirements rather than relying on an old itinerary."}], "source_name": "Venezia Unica", "source_url": "https://www.veneziaunica.it/en/sustainable-venice/enjoy-respect-venezia", "reading_minutes": 2}'::jsonb) on conflict(id) do nothing;
insert into public.guides(id,place_id,data) values('b0cb3252-5cc5-5078-a5e5-fb7b6a831abe','71cbb70e-1413-5fb9-85bc-9c8857fb36ce','{"title": "Lisbon Hills and Trams: Field Notes", "intro": "Trams, tiled streets and hilltop viewpoints give Lisbon an inviting rhythm for a flexible city day.", "sections": [{"title": "Choose a small area", "body": "Build a walk around one Lisbon neighborhood, adding a viewpoint or cultural stop along the way. The official tourism site organizes experiences by area and interest."}, {"title": "Plan the connections", "body": "Consult the official getting-around information before combining trams, walking and farther-away sights. Keep time for slopes and pauses; a short map distance can still make a full afternoon."}], "source_name": "Turismo de Lisboa", "source_url": "https://www.visitlisboa.com/en", "reading_minutes": 2}'::jsonb) on conflict(id) do nothing;
insert into public.guides(id,place_id,data) values('8d69926f-a1cc-5419-8021-f71955ca36d2','4ef64bb4-498a-55ab-8a24-e244e49252ec','{"title": "Swiss Alps: Field Notes", "intro": "Mountain rail journeys, snowy ridges and walking routes offer different ways into Switzerland''s Alpine landscapes.", "sections": [{"title": "Pick the right kind of day", "body": "Choose between a scenic rail journey, a valley walk and a demanding mountain route before adding stops. Distances on a map do not describe the effort of an Alpine trail."}, {"title": "Leave a flexible margin", "body": "Use the official hiking information to compare routes and preparation. Mountain weather and service availability affect plans, so keep another activity available if conditions change."}], "source_name": "Switzerland Tourism", "source_url": "https://www.myswitzerland.com/en-us/experiences/summer-autumn/hiking/", "reading_minutes": 2}'::jsonb) on conflict(id) do nothing;
insert into public.guides(id,place_id,data) values('c87245b5-6c29-5629-a957-93116d29553e','7117c66f-51a0-5b19-94dc-ebb4a4841f28','{"title": "Tower Bridge and the Thames: Field Notes", "intro": "Blue suspension spans, riverside paths and a working bridge create an absorbing London riverside stop.", "sections": [{"title": "See it from both banks", "body": "A riverside walk gives space to appreciate the towers and suspension spans. If you want to go inside, consult the official visitor page and book the experience that fits your day."}, {"title": "Look beyond the photograph", "body": "The visitor experience includes high-level walkways and the Victorian Engine Rooms. Check accessibility information and current bridge lift details before arranging a tightly timed visit."}], "source_name": "Tower Bridge", "source_url": "https://www.towerbridge.org.uk/", "reading_minutes": 2}'::jsonb) on conflict(id) do nothing;
insert into public.guides(id,place_id,data) values('36d14ba6-f206-5c1e-b578-1e6e733e61c6','35ffded9-bbbc-5988-8630-cc9d5df64ee9','{"title": "Park Guell, Barcelona: Field Notes", "intro": "Curving architecture, planted slopes and city views turn Park Guell into a distinctive Barcelona walk.", "sections": [{"title": "Plan before the climb", "body": "The park limits visitor capacity, so check availability before setting your day''s route. Its opening times change with the season; use current official information for your date."}, {"title": "Slow down inside", "body": "Leave time to notice details and the relationship between architecture and planting. The official site offers route, services, transport and guided-visit information to help shape a comfortable visit."}], "source_name": "Park Guell Official Website", "source_url": "https://parkguell.barcelona/en/planifica-la-teva-visita", "reading_minutes": 2}'::jsonb) on conflict(id) do nothing;
insert into public.guides(id,place_id,data) values('bee1d55a-f90c-5aef-b5b5-b1f4f4865656','aa21212b-b0d0-58ce-99be-ee3834bddf6d','{"title": "Santorini Caldera Villages: Field Notes", "intro": "Whitewashed settlements, volcanic cliffs and the Aegean horizon reveal Santorini''s layered island landscape.", "sections": [{"title": "Look beyond one viewpoint", "body": "Fira and Oia sit within a wider volcanic island landscape. Combine a caldera view with another settlement or one of the island''s contrasting beaches rather than building a day around a single image."}, {"title": "Taste the landscape", "body": "The island''s volcanic soil supports distinctive crops, including vines, small tomatoes and yellow split peas. Use the official destination information to explore food and cultural stops at an unhurried pace."}], "source_name": "Greek National Tourism Organisation", "source_url": "https://www.visitgreece.gr/en/islands/cyclades/santorini", "reading_minutes": 2}'::jsonb) on conflict(id) do nothing;
insert into public.guides(id,place_id,data) values('a7dd9e42-8919-5441-8528-99581e884b24','9c269449-085f-5cb3-ade1-652f28ca8e53','{"title": "Iceland Waterfalls: Field Notes", "intro": "A countrywide starting point for waterfall journeys. The photograph shows Dynjandi; video locations remain as credited by their creators.", "sections": [{"title": "Let conditions set the route", "body": "Weather can change quickly, and a beautiful scene does not show whether a road or path is suitable today. Consult current travel conditions before committing to a long drive."}, {"title": "Keep the view at a distance", "body": "Waterfall rocks can be slippery and some hazards are difficult to see. Respect signs, fences and marked paths. For longer independent outdoor trips, prepare suitable equipment and leave a travel plan."}], "source_name": "Visit Iceland", "source_url": "https://www.visiticeland.com/article/safe-travel-in-iceland/", "reading_minutes": 2}'::jsonb) on conflict(id) do nothing;
insert into public.guides(id,place_id,data) values('18231422-934f-5718-b0ff-47099a22d510','ea21d48f-af5a-5cf1-9435-5690e8edd4fc','{"title": "New York City: Field Notes", "intro": "Street-level energy and skyline views make New York a city best explored one neighborhood at a time.", "sections": [{"title": "Think in neighborhoods", "body": "Pick a neighborhood as the anchor for a morning or afternoon. A small number of nearby stops leaves more time for streets, food and unexpected discoveries."}, {"title": "Keep exploring", "body": "The city extends across five boroughs. Consult the official tourism site for current ideas and practical planning, then check the individual venue''s own information for reservations and access."}], "source_name": "NYC Tourism + Conventions", "source_url": "https://www.nyctourism.com/", "reading_minutes": 2}'::jsonb) on conflict(id) do nothing;
insert into public.guides(id,place_id,data) values('6fbff3dc-f149-5c7f-8ba7-633e8f67bc29','17a7552b-5573-5f31-a932-99214eca2db1','{"title": "Yosemite Valley: Field Notes", "intro": "Granite walls, waterfalls, forests and the Merced River frame an extraordinary Sierra Nevada valley.", "sections": [{"title": "Prepare before arriving", "body": "Use the National Park Service planning pages for current conditions, road access and reservation requirements. Lodging and camping need advance thought, while mobile coverage can be limited."}, {"title": "Stay with the landscape", "body": "Observe wildlife from a distance and never feed it. Near rivers and waterfalls, stay back from fast water and slippery rocks. Choose a walk that matches your preparation and available daylight."}], "source_name": "National Park Service", "source_url": "https://www.nps.gov/yose/planyourvisit/index.htm", "reading_minutes": 2}'::jsonb) on conflict(id) do nothing;
insert into public.guides(id,place_id,data) values('bd63ff90-3dd1-595d-b175-5e8764fbb355','4d3613c5-fd86-558f-b635-8c8e7484cc86','{"title": "Moraine Lake, Banff: Field Notes", "intro": "Turquoise water and the Valley of the Ten Peaks make Moraine Lake a memorable Canadian Rockies destination.", "sections": [{"title": "Start with access", "body": "Lake Louise and Moraine Lake are popular and need planning. The official Parks Canada page explains available transport and shuttle reservations; confirm the arrangements for your own travel date."}, {"title": "Make room in the day", "body": "Allow time for connections and potential queues rather than packing a lake visit between tight commitments. Separate park entry from transport planning and use the official information for current requirements."}], "source_name": "Parks Canada", "source_url": "https://parks.canada.ca/pn-np/ab/banff/visit/parkbus/louise", "reading_minutes": 2}'::jsonb) on conflict(id) do nothing;
insert into public.clips(id,place_id,publisher_id,data) values
('36aeba40-bcc7-5b77-b46d-40c752da41e3','7117c66f-51a0-5b19-94dc-ebb4a4841f28','470f3e27-4b1c-5a4c-ae90-c3d0fe9cb291','{"title": "Westminster on Foot", "caption": "Pedestrians gather in front of Elizabeth Tower and the Houses of Parliament on a sunny London afternoon.", "video_path": "catalog/shorts-2026-11-09/westminster-walk.mp4", "cover_path": "catalog/shorts-2026-11-09/westminster-walk.jpg", "source_url": "https://www.pexels.com/video/people-walking-near-big-ben-13986779/", "author": "Boyan Minchev", "duration": 12.0, "category": "Landmark walk", "feed_rank": 1}'::jsonb),
('f70c2836-512e-58ee-b4a4-a88abf11e0c8','ea21d48f-af5a-5cf1-9435-5690e8edd4fc','ae1fe04b-4e55-5710-b478-aa2a6f32f7d4','{"title": "Across the Brooklyn Bridge", "caption": "Walk the wooden pedestrian promenade past the bridge cables and stone arches in New York City.", "video_path": "catalog/shorts-2026-11-09/brooklyn-bridge-walk.mp4", "cover_path": "catalog/shorts-2026-11-09/brooklyn-bridge-walk.jpg", "source_url": "https://www.pexels.com/video/walking-on-brooklyn-bridge-in-nyc-31704457/", "author": "Daniela Sánchez", "duration": 5.791667, "category": "Landmark walk", "feed_rank": 2}'::jsonb),
('a7647473-1256-5bcf-aea0-9f3d033435c4','a42c1b6c-7fcc-51b7-837d-0ee7e3375fbe','fb7f92d7-981b-58ae-ad6d-8dafcf882afe','{"title": "A Walk Past the Colosseum", "caption": "Visitors cross the plaza outside the Roman amphitheater as daylight breaks through the clouds.", "video_path": "catalog/shorts-2026-11-09/colosseum-visitors.mp4", "cover_path": "catalog/shorts-2026-11-09/colosseum-visitors.jpg", "source_url": "https://www.pexels.com/video/visitors-walking-near-the-iconic-colosseum-36582031/", "author": "Hanna M", "duration": 8.0, "category": "Landmark walk", "feed_rank": 3}'::jsonb)
